(() => {
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(n)||0);
const today=()=>new Date().toISOString().slice(0,10);
const factors={'Poor':0.55,'Good':0.85,'Excellent':1};
const stages=['Acquired','Needs cleaning','Needs testing','Needs repair','Needs photos','Needs pricing','Ready to list','Listed','Offer received','Sold','Packaged','Dispatched','Delivered','Collected in store','Completed'];
const manufacturers=['Sony','Nintendo','Microsoft','Sega','Atari','SNK','NEC','Bandai','Hasbro','Mattel','LEGO','Nike','Adidas','Other'];
const state={view:'dashboard',activeItem:1,activeTab:'Overview',creditIssued:115,reportPeriod:'today',settings:{offerPct:45,storeCreditBonus:15,greenMargin:45,yellowMargin:30,pin:'2468',accessoryAllowances:{cables:10},fees:{eBay:{type:'percent',value:12.8},Vinted:{type:'percent',value:0},'In Store EPOS':{type:'fixed',value:0},'Manual / Cash':{type:'fixed',value:0},Website:{type:'percent',value:2.5}}},customers:[{id:1,name:'Sarah Green',credit:72.5,ledger:[[today(),'Opening demo balance',72.5]]},{id:2,name:'Mark Taylor',credit:25,ledger:[[today(),'Opening demo balance',25]]}],items:[
{id:1,title:'Silent Hill 2',manufacturer:'Sony',category:'Video Game',source:'Car Boot Sale',buy:35,baseMarket:84,condition:'Good',acquiredCondition:'Good',status:'Needs cleaning',location:'Shelf A2',velocity:78,notes:'Complete with manual.',photos:1,processingCosts:0,listing:null,sale:null,timeline:[['Acquired','Purchased at car boot sale.']]},
{id:2,title:'Nintendo 64 Console',manufacturer:'Nintendo',category:'Console',source:'Trade In',buy:48,baseMarket:116,condition:'Poor',acquiredCondition:'Poor',status:'Needs testing',location:'Bench 1',velocity:90,notes:'Controller included.',photos:0,processingCosts:4,listing:null,sale:null,timeline:[['Acquired','Customer trade-in accepted.']]},
{id:3,title:'1994 Power Rangers Figure',manufacturer:'Bandai',category:'Toy',source:'Other Reseller',buy:8,baseMarket:33,condition:'Good',acquiredCondition:'Good',status:'Completed',location:'Cabinet T3',velocity:64,notes:'Loose figure.',photos:3,processingCosts:1,listing:{channel:'In Store EPOS',price:39.99,date:today()},sale:{channel:'In Store EPOS',price:39.99,feeType:'fixed',feeValue:0,shipping:0,packaging:0,date:today(),status:'Collected in store'},timeline:[['Acquired','Dealer purchase.'],['Sold','Sold in store.'],['Completed','Collected in store.']]},
{id:4,title:'Vintage Nike Sweatshirt',manufacturer:'Nike',category:'Clothing',source:'Charity Shop',buy:12,baseMarket:52,condition:'Good',acquiredCondition:'Good',status:'Needs photos',location:'Rail C1',velocity:72,notes:'1990s label, size L.',photos:0,processingCosts:2,listing:null,sale:null,timeline:[['Acquired','Charity shop sourcing.']]},
{id:5,title:'PS3 Game Bundle',manufacturer:'Sony',category:'Video Game',source:'Private Seller',buy:28,baseMarket:82,condition:'Excellent',acquiredCondition:'Good',status:'Sold',location:'Dispatch Bay',velocity:88,notes:'Four-title bundle.',photos:5,processingCosts:3,listing:{channel:'eBay',price:74.99,date:today()},sale:{channel:'eBay',price:74.99,feeType:'percent',feeValue:12.8,shipping:4.2,packaging:.8,date:today(),status:'Ready to dispatch'},timeline:[['Acquired','Private collection purchase.'],['Listed','Listed on eBay.'],['Sold','Awaiting dispatch.']]}
]};
const root=$('#root'), modal=$('#modal'), backdrop=$('#backdrop');
const meta={dashboard:['Dashboard','HQ Today, workflow status and business health.'],acquisitions:['Acquisitions','Fast buying decisions with consistent rules.'],inventory:['Inventory','One record across the full lifecycle.'],processing:['Processing','Priority queue for work in progress.'],sales:['Sales','Sales and fulfilment linked to inventory.'],customers:['Trade Accounts','Store-credit balances and trade history.'],market:['HQ Market','Market-value education and demo intelligence.'],reports:['Reports','Margin, velocity and sales outcomes.'],settings:['Settings','Business rules and fee presets.'],item:['Item Workspace','One item. One record. One lifecycle.']};
const pill=(t,c='')=>`<span class="pill ${c}">${t}</span>`;
const metric=(a,b,c,action='')=>action?`<button class="metric" onclick="${action}"><span>${a}</span><strong>${b}</strong><small>${c}</small></button>`:`<div class="metric"><span>${a}</span><strong>${b}</strong><small>${c}</small></div>`;
function marketValue(i){if(i.valuation?.finalValue!=null)return Math.round(Number(i.valuation.finalValue)*100)/100;const base=Number(i.baseMarket)||0;return i.marketIsConditionSpecific?Math.round(base*100)/100:Math.round(base*(factors[i.condition]||.85)*100)/100;}
function acquisitionValue(i){return i.valuation?.acquisitionValue!=null?Number(i.valuation.acquisitionValue):marketValue(i);}
function missingEssentials(i){if(!i.accessories)return [];const p=i.valuation?.profile||{};const out=[];if(p.controller&&i.accessories.controller===false)out.push('Controller');if(p.cables&&i.accessories.cables===false)out.push('Cables');return out;}
function itemSignals(i){const out=[];if(i.needsIdentification)out.push(['Needs ID','warn']);if(i.needsValuation||marketValue(i)<=0)out.push(['Needs value','warn']);const miss=missingEssentials(i);if(miss.length)out.push(['Missing '+miss.join(' + '),'warn']);if(i.status==='Ready to list')out.push(['Ready to list','good']);if(i.sale?.status==='Ready to dispatch')out.push(['Ready to dispatch','warn']);if(i.valuation?.confidence==='adjusted')out.push(['Smart value','good']);return out;}
function signalHtml(i){const x=itemSignals(i);return x.length?`<div class="item-signals">${x.slice(0,3).map(v=>pill(v[0],v[1])).join('')}</div>`:'';}
function workflowTasks(){
 const tasks=[];
 state.items.forEach(i=>{
   let task=null;
   if(i.sale?.status==='Ready to dispatch')task={rank:1000,label:'Post this item',detail:i.title,item:i};
   else if(i.needsIdentification)task={rank:950,label:'Identify item',detail:i.title,item:i};
   else if(i.needsValuation||marketValue(i)<=0)task={rank:900,label:'Value item',detail:i.title,item:i};
   else {const miss=missingEssentials(i);if(miss.length)task={rank:875,label:'Resolve missing '+miss.join(' / '),detail:i.title,item:i};}
   if(!task&&i.status==='Ready to list')task={rank:850,label:'List this item',detail:i.title,item:i};
   else if(!task&&i.status?.startsWith('Needs'))task={rank:700+score(i),label:i.status.replace('Needs ','') ,detail:i.title+' · HQ '+score(i),item:i};
   if(task)tasks.push(task);
 });
 return tasks.sort((a,b)=>b.rank-a.rank);
}
function lifecycleStrip(i){const current=i.sale?.status||i.status;const core=['Acquired','Needs cleaning','Needs testing','Needs photos','Ready to list','Listed','Sold','Dispatched','Completed'];let idx=core.indexOf(current);if(current==='Collected in store'||current==='Delivered')idx=core.length-1;if(current==='Packaged')idx=6;if(idx<0)idx=Math.max(0,core.findIndex(x=>x===i.status));return `<div class="lifecycle-strip">${core.map((x,n)=>`<span class="${n<idx?'done':n===idx?'current':''}">${x.replace('Needs ','')}</span>`).join('')}</div>`;}
function valuationSummary(i){const v=i.valuation;if(!v)return `<div class="card"><h3>Valuation</h3><p class="muted">${i.needsValuation?'Needs valuation.':'Legacy valuation — no stored evidence breakdown yet.'}</p><strong>${money(marketValue(i))}</strong></div>`;const adjustments=(v.adjustments||[]);return `<div class="card valuation-summary"><div class="head"><h3>RetroHQ valuation</h3>${pill(v.confidence==='adjusted'?'Smart value':'Recorded value',v.confidence==='adjusted'?'good':'')}</div><div class="row"><span>${v.benchmarkLabel||'UK benchmark'}</span><strong>${money(v.benchmark)}</strong></div>${adjustments.map(a=>`<div class="row"><span>${a.label}</span><strong>−${money(a.amount)}</strong></div>`).join('')}<div class="row total"><span>RetroHQ UK Market Value</span><strong>${money(v.finalValue)}</strong></div>${(v.unresolved||[]).length?`<small class="warning-text">Still unresolved: ${v.unresolved.join(', ')}</small>`:''}<small class="muted">Captured ${v.timestamp||'during acquisition'} · ${v.source||'RetroHQ evidence'}</small></div>`;}
function daysToSell(i){if(!i.sale?.date||!i.acquiredDate)return null;return Math.max(0,Math.floor((new Date(i.sale.date)-new Date(i.acquiredDate))/(86400000)));}

function expected(i){const mv=marketValue(i),fee=mv*((state.settings.fees.eBay?.value||0)/100),cost=i.buy+i.processingCosts+fee,profit=mv-cost,margin=mv?profit/mv*100:0;return{mv,profit,margin};}
function soldEcon(i){if(!i.sale)return expected(i);const s=i.sale,fee=s.feeType==='percent'?s.price*s.feeValue/100:s.feeValue,total=i.buy+i.processingCosts+fee+(Number(s.shipping)||0)+(Number(s.packaging)||0),profit=s.price-total,margin=s.price?profit/s.price*100:0;return{mv:s.price,profit,margin};}
function marginClass(v){return v>=state.settings.greenMargin?'margin-green':v>=state.settings.yellowMargin?'margin-yellow':'margin-red';}
function marginBadge(v){const label=v>=state.settings.greenMargin?'Within target':v>=state.settings.yellowMargin?'Below target':'Outside rules';return `<span class="margin-badge ${marginClass(v)}"><strong>${v.toFixed(1)}%</strong><small>${label}</small></span>`;}
function score(i){const e=i.sale?soldEcon(i):expected(i);return Math.round(Math.min(100,Math.max(0,i.velocity*.55+Math.max(0,e.margin)*.675)));}
function acquisitionIntel(base,cond,paid=0,velocity=75){const conditionValue=Math.round((Number(base)||0)*(factors[cond]||.85)*100)/100;const recommended=Math.round(conditionValue*(state.settings.offerPct/100)*100)/100;const actual=Number(paid)||recommended;const margin=conditionValue?(conditionValue-actual)/conditionValue*100:0;const hq=Math.round(Math.min(100,Math.max(0,velocity*.55+Math.max(0,margin)*.675)));return{conditionValue,recommended,margin,hq};}
function completionClass(i){return ['Completed','Collected in store'].includes(i.status)||i.sale?.status==='Collected in store'?'good':'warn';}

function salePeriodMatch(i){
  if(!i.sale)return false;
  const d=new Date(i.sale.date||today()), now=new Date(today());
  const diff=Math.floor((now-d)/(1000*60*60*24));
  if(state.reportPeriod==='today')return diff===0;
  if(state.reportPeriod==='7')return diff<=6;
  return diff<=29;
}
function periodButtons(){
  return `<div class="segmented">
    <button class="${state.reportPeriod==='today'?'active':''}" onclick="setReportPeriod('today')">Today</button>
    <button class="${state.reportPeriod==='7'?'active':''}" onclick="setReportPeriod('7')">7 days</button>
    <button class="${state.reportPeriod==='30'?'active':''}" onclick="setReportPeriod('30')">30 days</button>
  </div>`;
}

function open(html){modal.innerHTML=html;backdrop.classList.remove('hidden');}
function closeModal(){backdrop.classList.add('hidden');modal.innerHTML='';}
function go(v){state.view=v;$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#title').textContent=meta[v][0];$('#subtitle').textContent=meta[v][1];$('#sidebar').classList.remove('open');render();}
function table(items){return `<div class="card tablewrap"><table class="table"><thead><tr><th>Item</th><th>Manufacturer</th><th>Condition</th><th>Buy</th><th>Market</th><th>Margin</th><th>HQ</th><th>Lifecycle</th><th>Sales</th></tr></thead><tbody>${items.map(i=>{const e=i.sale?soldEcon(i):expected(i);return `<tr class="click" onclick="openItem(${i.id})"><td><strong>${i.title}</strong><div class="muted">${i.category} · ${i.location}</div>${signalHtml(i)}</td><td>${i.manufacturer||'—'}</td><td>${i.condition}</td><td>${money(i.buy)}</td><td><strong>${i.needsValuation?'—':money(marketValue(i))}</strong>${i.valuation?.confidence==='adjusted'?'<small class="table-note">Smart value</small>':''}</td><td>${marginBadge(e.margin)}</td><td>${score(i)}</td><td>${pill(i.sale?.status||i.status,completionClass(i))}</td><td>${i.sale?.channel||i.listing?.channel||'—'}</td></tr>`}).join('')}</tbody></table></div>`;}
function dashboard(){
 const tasks=workflowTasks(),periodSales=state.items.filter(salePeriodMatch),salesValue=periodSales.reduce((a,i)=>a+(i.sale?.price||0),0),active=state.items.filter(i=>!['Completed','Collected in store'].includes(i.status));
 const needsValue=state.items.filter(i=>i.needsValuation||marketValue(i)<=0).length;
 return `<div class="hero"><div><small>RetroHQ · Test 8.1</small><h2>HQ Today</h2><p>Your business control panel — buy, process, sell and learn from one item record.</p></div><button class="btn primary" onclick="buyCheck()">🔎 Buy Check</button><button class="btn primary" onclick="quickBuy()">+ Quick acquisition</button></div>
 ${periodButtons()}
 <div class="grid metrics clickable-metrics">
 ${metric('Active inventory',active.length,'Open inventory →',"go('inventory')")}
 ${metric('Sales',money(salesValue),`${state.reportPeriod==='today'?'Today':state.reportPeriod+' days'} · Open sales →`,"go('sales')")}
 ${metric('Needs attention',tasks.length,`${needsValue} need valuation · Open queue →`,"go('processing')")}
 ${metric('Store credit outstanding',money(state.customers.reduce((a,c)=>a+c.credit,0)),'Open trade accounts →',"go('customers')")}
 </div>
 <div class="grid two"><div class="card"><div class="head"><h3>What should I do next?</h3>${pill('Live workflow','good')}</div>
 <div class="list">${tasks.slice(0,6).map(t=>`<div class="row"><button onclick="openItem(${t.item.id})"><strong>${t.label}</strong><span>${t.detail}</span></button>${pill('Priority',t.rank>=850?'warn':'')}</div>`).join('')}${!tasks.length?'<p class="muted">No urgent workflow tasks.</p>':''}</div></div>
 <div class="card"><div class="head"><h3>Lifecycle at a glance</h3>${pill('One item · one record','good')}</div>
 ${state.items.slice(0,5).map(i=>`<button class="mini-card" onclick="openItem(${i.id})"><span>${i.title}</span><strong>${i.sale?.status||i.status}</strong>${signalHtml(i)}</button>`).join('')}
 </div></div>`;
}
function acquisitions(){return `<div class="hero"><div><h2>Acquisition Engine</h2><p>Know the condition value, recommended offer, margin and HQ Score before you buy.</p></div><button class="btn primary" onclick="quickBuy()">+ Quick acquisition</button></div><div class="grid actions"><button class="action" onclick="tradeIn()"><span class="action-icon">🏪</span><strong>Trade in</strong><span>Cash, store credit or mixed payment.</span></button><button class="action" onclick="bundleModal('Sourcing Trip',false)"><span class="action-icon">🚗</span><strong>Sourcing trip</strong><span>Add multiple items under one trip.</span></button><button class="action" onclick="bundleModal('Other Reseller',false)"><span class="action-icon">🤝</span><strong>Other reseller</strong><span>Same margin and HQ rules.</span></button><button class="action" onclick="alert('Import centre remains planned for the core onboarding workflow.')"><span class="action-icon">⇧</span><strong>Import stock</strong><span>Existing database migration path.</span></button></div>${table(state.items)}`;}
function inventory(){return `<div class="toolbar"><input class="input" id="search" placeholder="Search items" oninput="filterItems()"><select class="select" id="cat" onchange="filterItems()"><option value="">All categories</option><option>Video Game</option><option>Console</option><option>Toy</option><option>Clothing</option></select><select class="select" id="attention" onchange="filterItems()"><option value="">All workflow states</option><option value="valuation">Needs valuation</option><option value="missing">Missing essentials</option><option value="ready">Ready to list</option><option value="sold">Sold</option></select><button class="btn primary" onclick="quickBuy()">+ Add item</button></div><div id="results">${table(state.items)}</div>`;}
function processing(){const tasks=workflowTasks();return `<div class="hero"><div><h2>Priority Processing Queue</h2><p>RetroHQ combines lifecycle work with missing intelligence and completeness issues.</p></div></div><div class="card"><div class="list">${tasks.map((t,n)=>`<div class="row workflow-task"><button onclick="openItem(${t.item.id},'Processing')"><strong>${n+1}. ${t.label}</strong><div class="muted">${t.detail} · ${t.item.status}</div></button><div>${signalHtml(t.item)} <button class="btn primary" onclick="openItem(${t.item.id},'Processing')">Open</button></div></div>`).join('')}${!tasks.length?'<p class="muted">Nothing currently needs attention.</p>':''}</div></div>`;}
function sales(){
 const sold=state.items.filter(i=>i.sale), filtered=sold.filter(salePeriodMatch);
 return `<div class="head"><div><h2>Sales</h2><p class="muted">Sales are part of the same item lifecycle.</p></div><button class="btn primary" onclick="manualSale()">+ Record sale</button></div>
 ${periodButtons()}
 <div class="grid metrics">
 ${metric('Sales value',money(filtered.reduce((a,i)=>a+i.sale.price,0)),state.reportPeriod==='today'?'Today':state.reportPeriod+' days')}
 ${metric('Items sold',filtered.length,'Selected period')}
 ${metric('Trade credit outstanding',money(state.customers.reduce((a,c)=>a+c.credit,0)),'Across trade accounts')}
 </div>
 ${table(sold)}
 <div class="card"><h3>Sales workflow</h3><p class="muted">Recording a sale updates the item lifecycle automatically. In-store collected sales complete immediately; online sales move to Sold / dispatch workflow.</p></div>`;
}
function customers(){return `<div class="hero"><div><h2>Trade Accounts</h2><p>Simple store-credit balances and a permanent transaction ledger.</p></div><button class="btn primary" onclick="newCustomer()">+ Trade account</button></div><div class="grid metrics">${metric('Credit issued',money(state.creditIssued),'Trade-in credit')}${metric('Outstanding',money(state.customers.reduce((a,c)=>a+c.credit,0)),'Customer liability')}${metric('Accounts',state.customers.length,'Trade accounts')}${metric('With credit',state.customers.filter(c=>c.credit>0).length,'Positive balances')}</div><div class="card"><div class="list">${state.customers.map(c=>`<div class="row"><button onclick="tradeAccount(${c.id})"><strong>${c.name}</strong><div class="muted">${c.ledger.length} ledger entries</div></button><strong>${money(c.credit)}</strong></div>`).join('')}</div></div>`;}
function market(){
 return `<div class="hero"><div><small>HQ Market</small><h2>Market intelligence</h2><p>Explore market direction without cluttering the core buy / process / sell workflow.</p></div>${pill('Demo intelligence','warn')}</div>
 <div class="grid two">
 <div class="card"><div class="head"><h3>Console market pulse</h3>${pill('Demo','')}</div>
 <div class="signal"><strong>PlayStation 3</strong><span>Strong collector interest</span></div>
 <div class="signal"><strong>GameCube</strong><span>Strong · low supply on key titles</span></div>
 <div class="signal"><strong>Dreamcast</strong><span>Rising · niche demand</span></div>
 <div class="signal"><strong>PlayStation 2</strong><span>Selective · horror / RPG strength</span></div>
 </div>
 <div class="card"><div class="head"><h3>Top movers</h3><button class="btn secondary" onclick="go('market')">Explore</button></div>
 <ol><li>Folklore — PS3</li><li>Afrika — PS3</li><li>Pokémon Emerald — GBA</li><li>Fire Emblem: Path of Radiance — GameCube</li><li>Silent Hill 2 — PS2</li><li>3D Dot Game Heroes — PS3</li><li>Kuon — PS2</li><li>Skies of Arcadia Legends — GameCube</li><li>Rule of Rose — PS2</li><li>Def Jam: Fight for NY — multi-platform</li></ol></div>
 </div>
 <div class="grid two">
 <div class="card"><h3>Investment watch</h3><ol><li>Late physical PS3 releases</li><li>GameCube exclusives</li><li>Survival horror</li><li>Dreamcast shooters</li><li>Mainline Pokémon</li><li>Low-print RPGs</li><li>Complete premium hardware</li><li>Collector editions</li><li>Regional exclusives</li><li>Sealed legacy titles</li></ol></div>
 <div class="card"><h3>Highest-value watch</h3><ol><li>Rare limited releases</li><li>Low-print survival horror</li><li>Premium boxed hardware</li><li>Graded / sealed flagship titles</li><li>Special editions</li><li>Developer / press items</li><li>Regional variants</li><li>Low-distribution RPGs</li><li>Complete collector bundles</li><li>Historically scarce accessories</li></ol></div>
 </div>
 <div class="card"><h3>Market evidence</h3><p>This prototype intentionally uses demonstration market intelligence. Live eBay / PriceCharting and future approved providers will feed this page later.</p></div>`;
}
function reports(){const sold=state.items.filter(i=>i.sale),avg=sold.length?sold.reduce((a,i)=>a+soldEcon(i).margin,0)/sold.length:0,profit=sold.reduce((a,i)=>a+soldEcon(i).profit,0),tracked=sold.filter(i=>i.valuation?.acquisitionValue!=null),accuracy=tracked.length?tracked.reduce((a,i)=>a+(1-Math.min(1,Math.abs(i.sale.price-i.valuation.acquisitionValue)/Math.max(1,i.valuation.acquisitionValue))),0)/tracked.length*100:null,days=sold.map(daysToSell).filter(x=>x!=null);return `<div class="grid metrics">${metric('Sales',sold.length,'Recorded outcomes')}${metric('Actual profit',money(profit),'After buy cost, fees and processing')}${metric('Avg sale margin',avg.toFixed(1)+'%','After fees')}${metric('Valuation accuracy',accuracy==null?'Building data':accuracy.toFixed(0)+'%',tracked.length+' closed-loop item(s)')}</div><div class="grid two"><div class="card"><h3>Buy → Sell feedback loop</h3><p>RetroHQ now retains the acquisition valuation and compares it with the eventual sale outcome.</p>${tracked.map(i=>`<div class="row"><span>${i.title}<small>Valued ${money(i.valuation.acquisitionValue)} → sold ${money(i.sale.price)}</small></span><strong>${money(soldEcon(i).profit)} profit</strong></div>`).join('')||'<p class="muted">Sell a Test 8.1 item to begin building closed-loop evidence.</p>'}</div><div class="card"><h3>Capital velocity</h3><div class="row"><span>Average days to sell</span><strong>${days.length?(days.reduce((a,b)=>a+b,0)/days.length).toFixed(1):'Building data'}</strong></div><div class="row"><span>Average HQ score</span><strong>${Math.round(state.items.reduce((a,i)=>a+score(i),0)/state.items.length)}/100</strong></div><p class="muted">As real transactions accumulate, these outcomes can improve future buying recommendations.</p></div></div>`;}
function settings(){return `<div class="grid two"><div class="card"><h3>Business Rules</h3><div class="formgrid"><div class="field"><label>Recommended offer %</label><input id="offerPct" class="input" type="number" value="${state.settings.offerPct}"></div><div class="field"><label>Store-credit bonus %</label><input id="creditBonus" class="input" type="number" value="${state.settings.storeCreditBonus}"></div><div class="field"><label>Green margin %</label><input id="green" class="input" type="number" value="${state.settings.greenMargin}"></div><div class="field"><label>Yellow margin %</label><input id="yellow" class="input" type="number" value="${state.settings.yellowMargin}"></div><div class="field"><label>Missing cable replacement allowance</label><input id="cableAllowance" class="input" type="number" step="0.01" value="${state.settings.accessoryAllowances?.cables??10}"><small class="muted">Your working replacement cost. Controller deductions use live CeX evidence where a confident match exists.</small></div></div><button class="btn primary" onclick="saveSettings()">Save rules</button></div><div class="card"><h3>Seller fee presets</h3>${Object.entries(state.settings.fees).map(([k,v])=>`<div class="row"><strong>${k}</strong><span>${v.value}${v.type==='percent'?'%':' fixed'}</span></div>`).join('')}<button class="btn secondary" onclick="editFeePreset()">Edit preset</button></div></div>`;}
function itemView(){const i=state.items.find(x=>x.id===state.activeItem);if(!i)return '<div class="card">Item not found.</div>';return `<div class="hero"><div><small>${i.category}</small><h2>${i.title}</h2><p>${i.condition} · ${i.location} · ${i.status}</p>${signalHtml(i)}</div><div><strong>${i.needsValuation?'Needs valuation':money(marketValue(i))}</strong><div class="muted">RetroHQ UK Market Value</div></div></div>${lifecycleStrip(i)}<div class="tabs">${['Overview','Acquisition','Processing','Market','Photos','Listing','Sales','Timeline','Notes'].map(t=>`<button class="tab ${state.activeTab===t?'active':''}" onclick="setTab('${t}')">${t}</button>`).join('')}</div>${itemTab(i)}`;}
function itemTab(i){const e=i.sale?soldEcon(i):expected(i);if(state.activeTab==='Overview')return `<div class="grid metrics">${metric('Market value',i.needsValuation?'—':money(marketValue(i)),i.valuation?'Stored smart valuation':'Legacy / pending evidence')}${metric('Expected profit',money(expected(i).profit),'At current market value')}${metric('HQ Score',score(i)+'/100','Margin + velocity')}${metric('Lifecycle',i.sale?.status||i.status,'Shared status')}</div><div class="grid two">${valuationSummary(i)}<div class="card"><h3>Completeness</h3>${i.accessories?`<div class="completeness-grid"><span>${i.accessories.box?'✓':'○'} Box</span><span>${i.accessories.controller?'✓':'○'} Controller</span><span>${i.accessories.cables?'✓':'○'} Cables</span></div>`:'<p class="muted">No completeness record yet.</p>'}${missingEssentials(i).length?`<p class="warning-text">Missing essential: ${missingEssentials(i).join(', ')}</p>`:''}</div></div>`;if(state.activeTab==='Acquisition')return `<div class="grid two"><div class="card"><div class="row"><span>Source</span><strong>${i.source}</strong></div><div class="row"><span>Buy price</span><strong>${money(i.buy)}</strong></div><div class="row"><span>Condition bought</span><strong>${i.acquiredCondition}</strong></div><div class="row"><span>Valuation when bought</span><strong>${i.valuation?.acquisitionValue!=null?money(i.valuation.acquisitionValue):'Not captured'}</strong></div><div class="row"><span>Recommended maximum</span><strong>${i.valuation?.recommendedMax!=null?money(i.valuation.recommendedMax):'—'}</strong></div></div>${valuationSummary(i)}</div>`;if(state.activeTab==='Processing')return `<div class="grid two"><div class="card"><h3>Lifecycle controls</h3><button class="btn secondary" onclick="previousStage(${i.id})">Previous stage</button> <button class="btn primary" onclick="nextStage(${i.id})">Next stage</button><div style="margin-top:12px"><button class="btn secondary" onclick="damageItem(${i.id})">Mark damaged</button> <button class="btn secondary" onclick="customerReturn(${i.id})">Customer return</button></div><div class="row" style="margin-top:12px"><span>Processing costs</span><strong>${money(i.processingCosts)}</strong></div><button class="btn secondary" onclick="addProcessingCost(${i.id})">+ Add processing cost</button></div><div class="card"><h3>Condition & completeness</h3><select class="select" onchange="updateCondition(${i.id},this.value)">${Object.keys(factors).map(c=>`<option ${c===i.condition?'selected':''}>${c}</option>`).join('')}</select>${i.accessories?`<div class="completeness-actions"><button class="btn secondary ${i.accessories.box?'included':''}" onclick="toggleAccessory(${i.id},'box')">${i.accessories.box?'✓':'○'} Box</button><button class="btn secondary ${i.accessories.controller?'included':''}" onclick="toggleAccessory(${i.id},'controller')">${i.accessories.controller?'✓':'○'} Controller</button><button class="btn secondary ${i.accessories.cables?'included':''}" onclick="toggleAccessory(${i.id},'cables')">${i.accessories.cables?'✓':'○'} Cables</button></div>`:''}<div style="margin-top:12px">${signalHtml(i)}</div><small class="muted">If condition worsens or an essential accessory is removed, RetroHQ flags the item for revaluation instead of silently reusing an old value.</small></div></div>`;if(state.activeTab==='Market')return `<div class="grid two">${valuationSummary(i)}<div class="card"><h3>Market intelligence</h3><div class="row"><span>Liquidity</span><strong>${i.velocity}/100</strong></div><div class="row"><span>Valuation confidence</span><strong>${i.valuation?.confidence||'Legacy'}</strong></div><p class="muted">Provider evidence and item-specific adjustments are retained with the item rather than recalculated differently on each screen.</p></div></div>`;if(state.activeTab==='Photos')return `<div class="card"><h3>Photos</h3><p>${i.photos} photo(s) recorded.</p><button class="btn primary" onclick="addPhoto(${i.id})">Add demo photo</button></div>`;if(state.activeTab==='Listing')return `<div class="card"><h3>Listing</h3>${i.listing?`<div class="row"><span>${i.listing.channel}</span><strong>${money(i.listing.price)}</strong></div>`:`<p class="muted">Not listed.</p><button class="btn primary" onclick="createListing(${i.id})">Create listing</button>`}</div>`;if(state.activeTab==='Sales')return `<div class="card"><h3>Sales</h3>${i.sale?`<div class="row"><span>Channel</span><strong>${i.sale.channel}</strong></div><div class="row"><span>Price</span><strong>${money(i.sale.price)}</strong></div><div class="row"><span>Actual profit</span><strong>${money(soldEcon(i).profit)}</strong></div><div class="row"><span>Fulfilment</span><strong>${i.sale.status}</strong></div>`:`<button class="btn primary" onclick="manualSale(${i.id})">Record sale</button>`}</div>`;if(state.activeTab==='Timeline')return `<div class="card"><h3>Permanent timeline</h3>${i.timeline.slice().reverse().map(t=>`<div class="row"><strong>${t[0]}</strong><span>${t[1]}</span></div>`).join('')}</div>`;return `<div class="card"><h3>Notes</h3><textarea id="notes" rows="7">${i.notes}</textarea><button class="btn primary" onclick="saveNotes(${i.id})">Save notes</button></div>`;}
function render(){const views={dashboard,acquisitions,inventory,processing,sales,customers,market,reports,settings,item:itemView};root.innerHTML=(views[state.view]||dashboard)();}
window.go=go;window.closeModal=closeModal;
window.openItem=(id,tab='Overview')=>{state.activeItem=id;state.activeTab=tab;go('item');};window.setTab=t=>{state.activeTab=t;render();};
window.filterItems=()=>{const q=($('#search')?.value||'').toLowerCase(),cat=$('#cat')?.value||'',attention=$('#attention')?.value||'';const items=state.items.filter(i=>(!cat||i.category===cat)&&(`${i.title} ${i.manufacturer} ${i.status} ${i.location}`.toLowerCase().includes(q))&&(!attention||(attention==='valuation'&&(i.needsValuation||marketValue(i)<=0))||(attention==='missing'&&missingEssentials(i).length)||(attention==='ready'&&i.status==='Ready to list')||(attention==='sold'&&!!i.sale)));$('#results').innerHTML=table(items);};

const researchQuery=()=>($('#qDesc')?.value||$('#bcDesc')?.value||'').trim();
const ebayUrl=(q,sold=false)=>`https://www.ebay.co.uk/sch/i.html?_nkw=${encodeURIComponent(q)}${sold?'&LH_Sold=1&LH_Complete=1':''}&LH_PrefLoc=1`;
const cexUrl=q=>`https://uk.webuy.com/search?stext=${encodeURIComponent(q)}`;
const googleUrl=q=>`https://www.google.com/search?q=${encodeURIComponent(q+' UK used price')}`;

window.buyCheck=()=>{window.buyCheckSession={pcId:null,cexId:null,cexVariants:[],condition:'Good'};open(`<h2>⚡ Buy Check</h2><p class="muted">Type or scan the item. RetroHQ handles identification, CeX grading and live evidence in the background.</p>
<div class="counter-search"><label>What is the item?</label><div class="counter-search-row"><input id="bcDesc" class="input counter-input" autofocus placeholder="e.g. PS3 Slim 320GB Scarlet Red" onkeydown="if(event.key==='Enter'){event.preventDefault();autoMarketSearch();}"><button id="autoSearchBtn" class="btn primary" onclick="autoMarketSearch()">Search</button></div><small class="muted">Press Enter to search. You will only be asked to confirm when RetroHQ is genuinely unsure.</small></div>
<div class="formgrid buy-basics"><div class="field"><label>Asking price (optional)</label><input id="bcAsk" class="input" type="number" step="0.01" placeholder="Not entered" oninput="buyCheckCalc()"></div><div class="field"><label>Barcode / EAN (optional)</label><input id="bcBarcode" class="input" inputmode="numeric" onkeydown="if(event.key==='Enter'){event.preventDefault();autoMarketSearch();}"></div></div>
<div class="buy-grade-card"><div><label>Condition</label><div class="quality-buttons"><button type="button" data-quality="Excellent" onclick="setBuyCondition('Excellent')">Excellent</button><button type="button" data-quality="Good" class="active" onclick="setBuyCondition('Good')">Good</button><button type="button" data-quality="Poor" onclick="setBuyCondition('Poor')">Poor</button></div></div><div><label>Included</label><div class="accessory-checks"><label id="bcBoxWrap"><input id="bcBox" type="checkbox" onchange="buyAccessoryChanged('box')"> <span id="bcBoxLabel">Box</span></label><label id="bcControllerWrap"><input id="bcController" type="checkbox" onchange="buyAccessoryChanged('controller')"> Controller</label><label id="bcCablesWrap"><input id="bcCables" type="checkbox" onchange="buyAccessoryChanged('cables')"> Cables</label></div></div><div id="bcGradeHint" class="grade-hint"></div></div>
<div id="autoSearchStatus" class="auto-status">Ready — type the item and press Enter.</div><div id="autoEvidence"></div>
<div class="formgrid value-fields"><div class="field"><label>RetroHQ UK Market Value</label><input id="bcMarket" class="input" type="number" readonly placeholder="Waiting for live UK evidence"></div><div class="field"><label>Manual override (optional)</label><input id="bcOverride" class="input" type="number" oninput="buyCheckCalc()"></div></div>
<div id="bcDecision" class="decision-panel"></div><div class="modal-actions"><button class="btn secondary" onclick="recordPass()">PASS</button><button class="btn secondary" onclick="recordWatch()">WATCH</button><button class="btn primary" onclick="buyFromCheck()">BUY → ACQUIRE</button></div>`);renderBuyGradeHint();buyCheckCalc();};

function identityCard(i){if(!i)return '';const attrs=i.attributes||{};const detail=[i.platform,attrs.revision,attrs.storage,attrs.colour].filter(Boolean);return `<div class="identity-lock"><div><strong>🔒 RetroHQ Identity Locked</strong><small>${i.confirmedProduct||i.label||'Confirmed item'}</small></div>${detail.length?`<div class="identity-tags">${detail.map(x=>`<span>${x}</span>`).join('')}</div>`:''}</div>`;}
function cexVariantCards(variants){return `<div class="cex-variant-list">${variants.map(v=>`<button class="cex-variant-card" onclick="chooseCexVariant('${String(v.productId||'').replace(/'/g,'')}','${String(v.grade||'').replace(/'/g,'')}')"><div class="cex-variant-top"><span class="cex-grade">${v.grade||'CeX variant'}</span><strong>${v.product||'Unknown CeX product'}</strong></div><div class="cex-price-grid"><span><small>Retail</small><b>${v.retail!=null?money(v.retail):'—'}</b></span><span><small>Cash</small><b>${v.cash!=null?money(v.cash):'—'}</b></span><span><small>Voucher</small><b>${v.voucher!=null?money(v.voucher):'—'}</b></span></div><span class="cex-select">Use this exact CeX record →</span></button>`).join('')}</div>`;}
function evidenceRow(x){
 if(x.provider==='CeX UK'&&x.status==='Live')return `<div class="evidence-row evidence-provider"><div class="provider-head"><span>CeX UK <em>(GBP)</em></span><span class="pill good">${x.selectedByUser?'Confirmed match':'Live'}</span></div><strong class="provider-product">${x.product||'Matched CeX record'}</strong><div class="provider-prices"><span><small>Retail</small><b>${x.retail!=null?money(x.retail):'—'}</b></span><span><small>Cash trade-in</small><b>${x.cash!=null?money(x.cash):'—'}</b></span><span><small>Voucher</small><b>${x.voucher!=null?money(x.voucher):'—'}</b></span></div><small>${x.grade?`CeX catalogue grade: ${x.grade} · `:''}${x.matchQuality?`Match: ${x.matchQuality}. `:''}${x.detail||''}</small>${x.selectedByUser?`<button class="btn secondary compact" onclick="changeCexMatch()">Change CeX match</button>`:''}</div>`;
 if(x.provider==='CeX UK'&&x.variants?.length){window.buyCheckSession.cexVariants=x.variants;return `<div class="evidence-row evidence-provider"><div class="provider-head"><span>CeX UK</span><span class="pill warn">Choose exact record</span></div><small>${x.detail||''}</small>${cexVariantCards(x.variants)}</div>`;}
 return `<div class="evidence-row"><span>${x.provider}${x.currency?` <em>(${x.currency})</em>`:''}</span><strong>${x.value!=null?money(x.value):x.status}</strong><small>${x.matchQuality?`Match: ${x.matchQuality} · `:''}${x.detail||''}</small></div>`;
}
function completenessProfile(identity){
 const type=identity?.type||'',platform=identity?.platform||'';
 if(type!=='hardware')return {box:true,controller:false,cables:false,label:'item'};
 if(['Game Boy Advance','Game Boy Color'].includes(platform))return {box:true,controller:false,cables:false,label:'handheld'};
 return {box:true,controller:true,cables:true,label:'console'};
}
function updateCompletenessUI(identity){
 const p=completenessProfile(identity);window.buyCheckSession.profile=p;
 const set=(id,on)=>{const el=$(id);if(el)el.classList.toggle('hidden',!on);};
 set('#bcBoxWrap',p.box);set('#bcControllerWrap',p.controller);set('#bcCablesWrap',p.cables);
 if($('#bcBoxLabel'))$('#bcBoxLabel').textContent=p.label==='item'?'Box / case':'Box';
}
async function loadAccessoryCosts(identity){
 const p=completenessProfile(identity);window.buyCheckSession.accessoryCosts={};
 if(!p.controller||!identity?.platform)return;
 try{const colour=(window.buyCheckSession?.condition||'Good')==='Poor'?'':(identity.attributes?.colour||'');const r=await fetch('/api/accessory-costs?'+new URLSearchParams({platform:identity.platform,colour}));const d=await r.json();if(d.controller?.ok)window.buyCheckSession.accessoryCosts.controller={amount:Number(d.controller.retail)||0,product:d.controller.product,source:'CeX UK live retail'};else window.buyCheckSession.accessoryCosts.controller=null;}catch(e){window.buyCheckSession.accessoryCosts.controller=null;}
}
function renderSmartValuation(){
 const s=window.buyCheckSession||{},box=$('#valuationBreakdown');if(!box)return;
 const v=s.valuation;if(!v){box.innerHTML='';return;}
 box.innerHTML=`<div class="smart-breakdown"><div class="row"><span>${v.benchmarkLabel}</span><strong>${money(v.benchmark)}</strong></div>${v.adjustments.map(a=>`<div class="row adjustment"><span>${a.label}<small>${a.source||''}</small></span><strong>−${money(a.amount)}</strong></div>`).join('')}<div class="row total"><span>RetroHQ UK Market Value</span><strong>${money(v.finalValue)}</strong></div>${v.unresolved.length?`<div class="unresolved"><strong>Needs attention</strong><span>${v.unresolved.join(' · ')}</span></div>`:''}</div>`;
}
function applySmartValuation(){
 const s=window.buyCheckSession||{},benchmark=Number(s.benchmark);if(!Number.isFinite(benchmark)){renderSmartValuation();buyCheckCalc();return;}
 const p=s.profile||completenessProfile(s.lockedIdentity),adjustments=[],unresolved=[];
 if(p.controller&&!$('#bcController')?.checked){
   const c=s.accessoryCosts?.controller;
   if(c?.amount>0)adjustments.push({type:'controller',label:'Missing controller replacement',amount:c.amount,source:c.product||c.source});
   else unresolved.push('Missing controller — no trusted replacement price found');
 }
 if(p.cables&&!$('#bcCables')?.checked){
   const amount=Math.max(0,Number(state.settings.accessoryAllowances?.cables)||0);
   if(amount>0)adjustments.push({type:'cables',label:'Missing essential cables allowance',amount,source:'RetroHQ business rule'});
   else unresolved.push('Missing cables — replacement allowance not configured');
 }
 const total=adjustments.reduce((a,x)=>a+x.amount,0),finalValue=Math.max(0,Math.round((benchmark-total)*100)/100);
 s.valuation={benchmark,benchmarkLabel:`CeX ${cexGradeForBuyCheck()} retail benchmark`,adjustments,unresolved,finalValue,acquisitionValue:finalValue,recommendedMax:Math.round(finalValue*(state.settings.offerPct/100)*100)/100,confidence:unresolved.length?'partial':adjustments.length?'adjusted':'benchmark',source:'CeX UK + RetroHQ item adjustments',timestamp:today(),profile:p,identity:s.lockedIdentity||null};
 if($('#bcMarket'))$('#bcMarket').value=finalValue.toFixed(2);renderSmartValuation();renderBuyGradeHint();buyCheckCalc();
}
window.renderMarketResult=async(d)=>{const status=$('#autoSearchStatus'),ev=$('#autoEvidence');if(d.pricechartingProductId)window.buyCheckSession.pcId=String(d.pricechartingProductId);
 if(d.needsRefinement){window.buyCheckSession.benchmark=null;window.buyCheckSession.valuation=null;$('#bcMarket').value='';status.textContent='One quick question — choose the console generation.';ev.innerHTML=`<div class="evidence-panel"><h3>Which one is it?</h3><div class="candidate-list">${(d.refinements||[]).map(r=>`<button class="candidate-card" onclick="refineMarketSearch('${String(r.query).replace(/'/g,'')}')"><strong>${r.label}</strong><small>Use this generation</small></button>`).join('')}</div></div>`;buyCheckCalc();return;}
 if(d.needsConfirmation){window.buyCheckSession.benchmark=null;window.buyCheckSession.valuation=null;$('#bcMarket').value='';status.textContent='RetroHQ found more than one credible match.';ev.innerHTML=`<div class="evidence-panel"><h3>Which item is this?</h3><div class="candidate-list">${(d.candidates||[]).slice(0,6).map(c=>`<button class="candidate-card" onclick="selectMarketCandidate('${String(c.id).replace(/'/g,'')}')"><strong>${c['product-name']||'Unknown product'}</strong><span>${c['console-name']||'Unknown platform'}</span><small>Use this item</small></button>`).join('')}</div></div>`;buyCheckCalc();return;}
 window.buyCheckSession.lockedIdentity=d.lockedIdentity||null;window.buyCheckSession.benchmark=d.marketValue!=null?Number(d.marketValue):null;window.buyCheckSession.evidence=d.evidence||[];
 updateCompletenessUI(d.lockedIdentity);
 if(d.marketValue!=null){status.textContent='✓ Answer ready — valuing the actual item in front of you.';}else{$('#bcMarket').value='';status.textContent=(d.evidence||[]).some(x=>x.provider==='PriceCharting'&&x.status==='Live')?'Reference found — waiting for usable UK pricing evidence.':'No confident live UK value found.';}
 ev.innerHTML=`<details class="evidence-details"><summary>Why this value?</summary><div class="evidence-panel"><div id="valuationBreakdown"></div>${identityCard(d.lockedIdentity)}${(d.evidence||[]).map(evidenceRow).join('')}<small class="muted method-note">${d.method||''}</small></div></details>`;
 await loadAccessoryCosts(d.lockedIdentity);applySmartValuation();};
window.runConfirmedSearch=async({cexId=null,cexGrade=null}={})=>{const q=($('#bcDesc')?.value||'').trim(),barcode=($('#bcBarcode')?.value||'').trim(),status=$('#autoSearchStatus'),ev=$('#autoEvidence'),btn=$('#autoSearchBtn');if(!q&&!barcode)return alert('Enter a description or barcode first.');btn.disabled=true;status.textContent='Loading evidence for the locked identity…';try{const p=new URLSearchParams({q,barcode,cexGrade:cexGrade??cexGradeForBuyCheck()});if(window.buyCheckSession?.pcId)p.set('id',window.buyCheckSession.pcId);if(cexId)p.set('cexId',cexId);const r=await fetch('/api/market-search?'+p);await renderMarketResult(await r.json());}catch(err){status.textContent='Market connector unavailable.';ev.innerHTML=`<div class="provider-warning">${err.message}</div>`;}finally{btn.disabled=false;}};
window.autoMarketSearch=async()=>{const keepCondition=window.buyCheckSession?.condition||'Good';window.buyCheckSession={pcId:null,cexId:null,cexVariants:[],condition:keepCondition};const q=($('#bcDesc')?.value||'').trim(),barcode=($('#bcBarcode')?.value||'').trim();if(!q&&!barcode)return alert('Enter a description or barcode first.');const status=$('#autoSearchStatus'),ev=$('#autoEvidence'),btn=$('#autoSearchBtn');btn.disabled=true;status.textContent='Identifying item and searching live market providers…';try{const p=new URLSearchParams({q,barcode,cexGrade:cexGradeForBuyCheck()});const r=await fetch('/api/market-search?'+p);await renderMarketResult(await r.json());}catch(err){status.textContent='Market connector unavailable.';ev.innerHTML=`<div class="provider-warning">${err.message}</div>`;}finally{btn.disabled=false;}};
window.refineMarketSearch=async(query)=>{const desc=$('#bcDesc');desc.value=query;const keepCondition=window.buyCheckSession?.condition||'Good';window.buyCheckSession={pcId:null,cexId:null,cexVariants:[],condition:keepCondition};const status=$('#autoSearchStatus'),ev=$('#autoEvidence'),btn=$('#autoSearchBtn');btn.disabled=true;status.textContent='Searching exact console generation…';try{const p=new URLSearchParams({q:query,barcode:'',cexGrade:cexGradeForBuyCheck()});const r=await fetch('/api/market-search?'+p);await renderMarketResult(await r.json());}catch(err){status.textContent='Market connector unavailable.';ev.innerHTML=`<div class="provider-warning">${err.message}</div>`;}finally{btn.disabled=false;}};
window.selectMarketCandidate=async(id)=>{window.buyCheckSession.pcId=String(id);window.buyCheckSession.cexId=null;const q=($('#bcDesc')?.value||'').trim(),status=$('#autoSearchStatus'),ev=$('#autoEvidence');status.textContent='Locking identity and loading market evidence…';try{const p=new URLSearchParams({q,id,cexGrade:cexGradeForBuyCheck()});const r=await fetch('/api/market-search?'+p);await renderMarketResult(await r.json());}catch(err){status.textContent='Market connector unavailable.';ev.innerHTML=`<div class="provider-warning">${err.message}</div>`;}};
window.chooseCexVariant=async(productId,grade)=>{if(!productId)return;window.buyCheckSession.cexId=productId;await runConfirmedSearch({cexId:productId,cexGrade:grade||cexGradeForBuyCheck()});};
window.changeCexMatch=async()=>{window.buyCheckSession.cexId=null;await runConfirmedSearch({cexId:null,cexGrade:cexGradeForBuyCheck()});};
window.cexGradeForBuyCheck=()=>{const condition=window.buyCheckSession?.condition||'Good';if(condition==='Poor')return 'Discounted';return $('#bcBox')?.checked?'Boxed':'Unboxed';};
window.renderBuyGradeHint=()=>{const box=$('#bcGradeHint');if(!box)return;const grade=cexGradeForBuyCheck(),condition=window.buyCheckSession?.condition||'Good',v=window.buyCheckSession?.valuation,p=window.buyCheckSession?.profile||{};box.innerHTML=`<strong>CeX comparison: ${grade}</strong><span>Chosen automatically from ${condition.toLowerCase()} condition${condition==='Poor'?'':' + '+($('#bcBox')?.checked?'box included':'no box')}. </span>${v?.adjustments?.length?`<small>RetroHQ has deducted ${money(v.adjustments.reduce((a,x)=>a+x.amount,0))} for missing essentials from the CeX benchmark.</small>`:''}${v?.unresolved?.length?`<small>⚠ ${v.unresolved.join(' · ')}</small>`:''}${!v&&((p.controller&&!$('#bcController')?.checked)||(p.cables&&!$('#bcCables')?.checked))?'<small>Missing essentials will be valued after the product is identified.</small>':''}`;};
window.setBuyCondition=async(condition)=>{window.buyCheckSession=window.buyCheckSession||{};window.buyCheckSession.condition=condition;$('.quality-buttons button').forEach(b=>b.classList.toggle('active',b.dataset.quality===condition));renderBuyGradeHint();buyCheckCalc();if(window.buyCheckSession.pcId){window.buyCheckSession.cexId=null;await runConfirmedSearch({cexGrade:cexGradeForBuyCheck()});}else applySmartValuation();};
window.buyAccessoryChanged=async(kind)=>{renderBuyGradeHint();if(kind==='box'&&window.buyCheckSession?.pcId){window.buyCheckSession.cexId=null;await runConfirmedSearch({cexGrade:cexGradeForBuyCheck()});return;}applySmartValuation();};

window.renderBuyLinks=()=>{const q=($('#bcDesc')?.value||'').trim();const box=$('#bcLinks');if(!box)return;box.innerHTML=q?`<div class="live-research"><strong>Live UK research</strong><div class="research-buttons"><a class="btn secondary" target="_blank" rel="noopener" href="${ebayUrl(q,false)}">eBay UK active ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${ebayUrl(q,true)}">eBay UK sold ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${cexUrl(q)}">CeX UK ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${googleUrl(q)}">Google UK ↗</a></div><small class="muted">These open the real provider search using your description. Values are not imported into RetroHQ yet.</small></div>`:`<p class="muted">Enter a description to generate live research links.</p>`;};

window.buyCheckCalc=()=>{const askRaw=$('#bcAsk')?.value?.trim()??'',ask=askRaw===''?null:Number(askRaw),autoRaw=$('#bcMarket')?.value?.trim()??'',ovRaw=$('#bcOverride')?.value?.trim()??'',auto=autoRaw===''?null:Number(autoRaw),ov=ovRaw===''?null:Number(ovRaw),market=ov!=null?ov:auto,box=$('#bcDecision');if(!box)return;if(market==null||!Number.isFinite(market)){box.innerHTML=`<p class="muted">Enter an item and press Enter. RetroHQ will calculate the answer automatically.</p>`;return;}const max=market*(state.settings.offerPct/100),margin=ask!=null&&market?((market-ask)/market*100):null,diff=ask==null?null:max-ask,decision=ask==null?'ENTER ASKING PRICE':diff>=0?'BUY — INSIDE TARGET':'OVER TARGET';box.innerHTML=`<div><span>RetroHQ UK Market Value</span><strong>${money(market)}</strong><small>${ov!=null?'Manual override':'Value of this item after known adjustments'}</small></div><div class="focus"><span>Maximum buy</span><strong>${money(max)}</strong><small>${state.settings.offerPct}% target buy rate</small></div><div><span>Seller asking</span><strong>${ask==null?'Not entered':money(ask)}</strong><small>${ask==null?'Add it for a buy/pass answer':diff>=0?money(diff)+' inside target':money(Math.abs(diff))+' over target'}</small></div><div class="${ask==null?'':'decision-answer '+(diff>=0?'buy':'over')}"><span>Decision</span><strong>${decision}</strong><small>${margin==null?'':margin.toFixed(1)+'% headline spread'}</small></div>`;};
window.recordPass=()=>{const d=$('#bcDesc').value.trim(),raw=$('#bcAsk').value.trim(),ask=raw===''?null:Number(raw);if(!d)return alert('Describe the item first.');state.researchHistory=state.researchHistory||[];state.researchHistory.push({date:new Date().toISOString(),description:d,asking:ask,decision:'PASS'});closeModal();alert('Pass recorded in research history. No inventory item was created.');};
window.recordWatch=()=>{const d=$('#bcDesc').value.trim(),raw=$('#bcAsk').value.trim(),ask=raw===''?null:Number(raw);if(!d)return alert('Describe the item first.');state.researchHistory=state.researchHistory||[];state.researchHistory.push({date:new Date().toISOString(),description:d,asking:ask,decision:'WATCH'});closeModal();alert('Saved to research/watch history. No inventory item was created.');};
window.buyFromCheck=()=>{const session=window.buyCheckSession||{},overrideRaw=$('#bcOverride')?.value?.trim()||'',market=overrideRaw||$('#bcMarket').value,valuation=session.valuation?JSON.parse(JSON.stringify(session.valuation)):null;if(valuation&&overrideRaw){valuation.finalValue=Number(overrideRaw);valuation.acquisitionValue=Number(overrideRaw);valuation.recommendedMax=Math.round(Number(overrideRaw)*(state.settings.offerPct/100)*100)/100;valuation.source='Manual override over stored evidence';valuation.confidence='override';}const seed={desc:$('#bcDesc').value.trim(),barcode:$('#bcBarcode').value.trim(),ask:$('#bcAsk').value,market,cond:session.condition||'Good',marketIsConditionSpecific:true,accessories:{box:$('#bcBox')?.checked||false,controller:$('#bcController')?.checked||false,cables:$('#bcCables')?.checked||false},cexGrade:cexGradeForBuyCheck(),valuation,identity:session.lockedIdentity||null};quickBuy(seed);};

window.quickBuy=(seed={})=>{open(`<h2>⚡ Quick Acquisition</h2><p class="muted">Already bought it? Capture it quickly. Unknown details can be completed later.</p>
<div class="identify-box"><div class="identify-tabs"><button class="btn secondary" onclick="$('#qBarcode').focus()">▥ Barcode</button><button class="btn secondary" onclick="photoIdentify()">▣ Photo</button><button class="btn secondary" onclick="$('#qDesc').focus()">⌕ Description</button></div><div class="formgrid"><div class="field full"><label>Describe the item</label><input id="qDesc" class="input" placeholder="e.g. Pokémon Emerald GBA PAL cartridge only" value="${(seed.desc||'').replace(/"/g,'&quot;')}" oninput="parseDescription();renderQuickLinks()"><small class="muted">Loose/unboxed items are fine — describe what you know.</small></div><div class="field"><label>Barcode / EAN</label><input id="qBarcode" class="input" inputmode="numeric" value="${seed.barcode||''}"></div><div class="field"><label>Identification status</label><div id="identifyStatus" class="evidence-status">${seed.desc?'Carried from Buy Check':'Waiting for confirmation'}</div></div></div><button class="btn primary" onclick="findCandidates()">Find likely matches</button><div id="candidateBox"></div><div id="qLinks"></div></div>
<div class="formgrid"><div class="field full"><label>Confirmed item / title</label><input id="qTitle" class="input" value="${(seed.desc||'').replace(/"/g,'&quot;')}"></div><div class="field"><label>Category</label><select id="qCat" class="select"><option>Video Game</option><option>Console</option><option>Toy</option><option>Clothing</option><option>Accessory</option><option>Collectible</option></select></div><div class="field"><label>Manufacturer</label><select id="qMan" class="select">${manufacturers.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Condition</label><select id="qCond" class="select" onchange="updateQuickIntel()">${Object.keys(factors).map(x=>`<option ${x===(seed.cond||'Good')?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Included</label><div class="accessory-checks quick-accessories"><label><input id="qBox" type="checkbox" ${seed.accessories?.box?'checked':''}> Box</label><label><input id="qController" type="checkbox" ${seed.accessories?.controller?'checked':''}> Controller</label><label><input id="qCables" type="checkbox" ${seed.accessories?.cables?'checked':''}> Cables</label></div></div><div class="field"><label>Region</label><select id="qRegion" class="select"><option>UK / PAL</option><option>Europe / PAL</option><option>USA / NTSC</option><option>Japan / NTSC-J</option><option>Region free / N/A</option><option>Unknown</option></select></div><div class="field"><label>Area</label><input id="qArea" class="input" placeholder="e.g. Stockroom"></div><div class="field"><label>Shelf</label><input id="qShelf" class="input" placeholder="e.g. B2"></div></div>
<div class="formgrid"><div class="field"><label>Verified UK market value</label><input id="qMarket" class="input" type="number" value="${seed.market||''}" oninput="updateQuickIntel()" placeholder="Optional now"></div><div class="field"><label>Amount paid</label><input id="qBuy" class="input" type="number" value="${seed.ask||''}" oninput="updateQuickIntel()"></div></div><div id="qIntel" class="decision-panel"></div>
<div class="modal-actions"><button class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn secondary" onclick="saveQuickBuy(true)">Save & next</button><button class="btn primary" onclick="saveQuickBuy(false)">Save item</button></div>`);window.quickBuySeed=seed;if(seed.identity?.type==='hardware')$('#qCat').value='Console';const platform=seed.identity?.platform||'';if(/^PlayStation/.test(platform))$('#qMan').value='Sony';else if(/^Xbox/.test(platform))$('#qMan').value='Microsoft';else if(/Game Boy|Nintendo/.test(platform))$('#qMan').value='Nintendo';parseDescription();renderQuickLinks();updateQuickIntel();};

window.renderQuickLinks=()=>{const q=($('#qDesc')?.value||'').trim(),box=$('#qLinks');if(!box)return;box.innerHTML=q?`<div class="live-research"><strong>Live research links</strong><div class="research-buttons"><a class="btn secondary" target="_blank" rel="noopener" href="${ebayUrl(q,false)}">eBay active ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${ebayUrl(q,true)}">eBay sold ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${cexUrl(q)}">CeX UK ↗</a><a class="btn secondary" target="_blank" rel="noopener" href="${googleUrl(q)}">Google UK ↗</a></div></div>`:'';};
window.photoIdentify=()=>alert('Photo identification is not connected yet. Description and barcode remain available.');
window.parseDescription=()=>{const d=($('#qDesc')?.value||'').toLowerCase();if(d.includes('pal')||d.includes(' uk'))$('#qRegion').value='UK / PAL';};
window.findCandidates=()=>{const d=$('#qDesc').value.trim(),b=$('#qBarcode').value.trim();if(!d&&!b)return alert('Enter a description or barcode first.');/* refresh identity-dependent fields, preserve price/location */$('#qTitle').value='';$('#qMan').selectedIndex=0;$('#qCat').selectedIndex=0;$('#identifyStatus').textContent='New search · confirmation required';$('#candidateBox').innerHTML=`<div class="candidate"><strong>New search:</strong> ${[d,b&&`EAN ${b}`].filter(Boolean).join(' · ')}<br><small class="muted">Previous identification cleared. Confirm/refine the item below. Live catalogue matching comes with the data connector.</small></div>`;$('#qTitle').value=d;renderQuickLinks();};
window.updateQuickIntel=()=>{const raw=$('#qMarket')?.value?.trim()??'',base=raw===''?null:Number(raw),cond=$('#qCond')?.value||'Good',paidRaw=$('#qBuy')?.value?.trim()??'',paid=paidRaw===''?null:Number(paidRaw);if(base==null||!Number.isFinite(base)){ $('#qIntel').innerHTML=`<p class="muted">Market value can be left unknown. The item will be flagged for later valuation.</p>`;return;}const conditionSpecific=window.quickBuySeed?.marketIsConditionSpecific===true,adj=conditionSpecific?base:base*(factors[cond]||1),rec=adj*(state.settings.offerPct/100),m=paid!=null&&adj?((adj-paid)/adj*100):null;$('#qIntel').innerHTML=`<div><span>${conditionSpecific?'UK value':'Condition-adjusted UK value'}</span><strong>${money(adj)}</strong></div><div><span>Configured max buy</span><strong>${money(rec)}</strong><small>${state.settings.offerPct}% target buy rate</small></div><div><span>Expected margin</span><strong class="${m==null?'':marginClass(m)}">${m==null?'—':m.toFixed(1)+'%'}</strong></div>`;};
window.saveQuickBuy=(next=false)=>{const title=($('#qTitle').value||$('#qDesc').value).trim(),buy=Number($('#qBuy').value||0),marketRaw=$('#qMarket').value,market=marketRaw===''?null:Number(marketRaw);if(!title)return alert('Enter at least a description/title.');const area=$('#qArea').value.trim(),shelf=$('#qShelf').value.trim(),seed=window.quickBuySeed||{},accessories={box:$('#qBox')?.checked||false,controller:$('#qController')?.checked||false,cables:$('#qCables')?.checked||false},valuation=seed.valuation?JSON.parse(JSON.stringify(seed.valuation)):null;if(valuation){valuation.finalValue=market;valuation.acquisitionValue=market;valuation.recommendedMax=Math.round((Number(market)||0)*(state.settings.offerPct/100)*100)/100;valuation.profile=valuation.profile||completenessProfile(seed.identity);}state.items.push({id:Date.now(),title,manufacturer:$('#qMan').value,category:$('#qCat').value,source:'Quick Acquisition',buy,baseMarket:market,marketIsConditionSpecific:true,valuation,needsIdentification:!seed.identity,needsValuation:market===null,condition:$('#qCond').value,acquiredCondition:$('#qCond').value,accessories,cexGrade:seed.cexGrade||null,identity:seed.identity||null,region:$('#qRegion').value,barcode:$('#qBarcode').value.trim(),searchDescription:$('#qDesc').value.trim(),area,shelf,location:[area,shelf].filter(Boolean).join(' / ')||'Unassigned',velocity:70,acquiredDate:today(),notes:market===null?'Needs valuation':'',photos:0,processingCosts:0,listing:null,sale:null,timeline:[['Acquired',market===null?'Quick captured · valuation required.':`Acquired at ${money(buy)} against RetroHQ value ${money(market)}.`],...(valuation?[['Valuation',`${valuation.benchmarkLabel||'UK benchmark'} ${money(valuation.benchmark)} → RetroHQ ${money(valuation.finalValue)}.`]]:[])]});if(next){quickBuy();}else{closeModal();go('inventory');}};
window.bundleModal=(type,credit)=>{open(`<h2>${type}</h2>${credit?`<div class="formgrid"><div class="field"><label>Trade account</label><select id="tradeCustomer" class="select"><option value="">Walk-in / none</option>${state.customers.map(c=>`<option value="${c.id}">${c.name} · ${money(c.credit)} credit</option>`).join('')}</select></div><div class="field"><label>Payment method</label><select id="offerType" class="select" onchange="toggleMixed()"><option>Cash</option><option>Store Credit</option><option>Mixed</option></select></div><div class="field mixed hidden"><label>Cash part</label><input id="mixedCash" class="input" type="number"></div><div class="field mixed hidden"><label>Store-credit part</label><input id="mixedCredit" class="input" type="number"></div></div>`:''}<div id="bundleRows">${bundleRow()}</div><div class="modal-actions"><button class="btn secondary" onclick="addBundleRow()">+ Add item</button><button class="btn primary" onclick="saveBundle('${type}',${credit})">Complete</button></div>`);updateBundleIntel();};
function bundleRow(){return `<div class="bundle-row"><input class="input bt" placeholder="Item title"><select class="select bman">${manufacturers.map(x=>`<option>${x}</option>`).join('')}</select><select class="select bcond" onchange="updateBundleIntel()">${Object.keys(factors).map(x=>`<option>${x}</option>`).join('')}</select><input class="input bm" type="number" placeholder="Excellent value" oninput="updateBundleIntel()"><input class="input bo" type="number" placeholder="Amount paid" oninput="updateBundleIntel()"><div class="bundle-intel"></div></div>`;}
window.addBundleRow=()=>{$('#bundleRows').insertAdjacentHTML('beforeend',bundleRow());updateBundleIntel();};window.toggleMixed=()=>$$('.mixed').forEach(x=>x.classList.toggle('hidden',$('#offerType').value!=='Mixed'));window.updateBundleIntel=()=>$$('.bundle-row').forEach(r=>{const x=acquisitionIntel(Number(r.querySelector('.bm').value),r.querySelector('.bcond').value,Number(r.querySelector('.bo').value));r.querySelector('.bundle-intel').innerHTML=`<small>Condition ${money(x.conditionValue)}</small><strong>Offer ${money(x.recommended)} · Margin ${x.margin.toFixed(0)}% · HQ ${x.hq}</strong>`;});
window.saveBundle=(type,credit)=>{const kind=credit?$('#offerType').value:'Cash',customer=credit&&$('#tradeCustomer').value?state.customers.find(c=>c.id===Number($('#tradeCustomer').value)):null;let creditAdd=0;$$('.bundle-row').forEach((r,n)=>{const title=r.querySelector('.bt').value;if(!title)return;const cond=r.querySelector('.bcond').value,base=Number(r.querySelector('.bm').value),x=acquisitionIntel(base,cond,Number(r.querySelector('.bo').value)),cash=Number(r.querySelector('.bo').value)||x.recommended;let buy=cash;if(kind==='Store Credit'){buy=cash*(1+state.settings.storeCreditBonus/100);creditAdd+=buy;}state.items.push({id:Date.now()+n,title,manufacturer:r.querySelector('.bman').value,category:'Video Game',source:type,buy,baseMarket:base||buy*2,condition:cond,acquiredCondition:cond,status:'Needs cleaning',location:'Unassigned',velocity:75,notes:'',photos:0,processingCosts:0,listing:null,sale:null,timeline:[['Acquired',`${type}; ${kind}.`]]});});if(kind==='Mixed'){creditAdd=Number($('#mixedCredit').value)||0;}if(customer&&creditAdd){customer.credit+=creditAdd;customer.ledger.push([today(),kind+' trade-in credit',creditAdd]);state.creditIssued+=creditAdd;}closeModal();go('inventory');};
window.tradeAccount=id=>{const c=state.customers.find(x=>x.id===id);open(`<h2>${c.name}</h2><div class="hero"><div><small>Available store credit</small><h2>${money(c.credit)}</h2></div></div>${c.ledger.map(x=>`<div class="row"><span>${x[0]} · ${x[1]}</span><strong>${money(x[2])}</strong></div>`).join('')}`);};window.newCustomer=()=>{const name=prompt('Customer name');if(name){state.customers.push({id:Date.now(),name,credit:0,ledger:[]});render();}};
window.nextStage=id=>{const i=state.items.find(x=>x.id===id),idx=stages.indexOf(i.status);if(idx<stages.length-1){i.status=stages[idx+1];i.timeline.push([i.status,'Moved to next stage.']);render();}};window.previousStage=id=>{const i=state.items.find(x=>x.id===id),idx=stages.indexOf(i.status);if(idx>0){i.status=stages[idx-1];i.timeline.push([i.status,'Stage reversed; previous history retained.']);render();}};
window.markValuationStale=(i,reason)=>{i.needsValuation=true;if(i.valuation){i.valuation.stale=true;i.valuation.confidence='stale';}i.timeline.push(['Revaluation required',reason]);};
window.damageItem=id=>{const i=state.items.find(x=>x.id===id);i.status='Needs repair';markValuationStale(i,'Damage discovered; previous valuation retained as history but is no longer current.');i.timeline.push(['Needs repair','Damage discovered.']);render();};
window.customerReturn=id=>{const i=state.items.find(x=>x.id===id);i.status='Needs testing';i.timeline.push(['Customer return','Returned item re-entered lifecycle.']);render();};
window.updateCondition=(id,c)=>{const i=state.items.find(x=>x.id===id),old=i.condition;if(old===c)return;i.condition=c;markValuationStale(i,`Condition changed ${old} → ${c}.`);i.timeline.push(['Condition changed',`${old} → ${c}`]);render();};
window.toggleAccessory=(id,key)=>{const i=state.items.find(x=>x.id===id);if(!i.accessories)return;i.accessories[key]=!i.accessories[key];const label=key[0].toUpperCase()+key.slice(1);if(i.accessories[key]&&i.valuation){i.valuation.adjustments=(i.valuation.adjustments||[]).filter(a=>a.type!==key);i.valuation.unresolved=(i.valuation.unresolved||[]).filter(x=>!x.toLowerCase().includes(key==='controller'?'controller':'cable'));const deduction=i.valuation.adjustments.reduce((a,x)=>a+Number(x.amount||0),0);i.valuation.finalValue=Math.max(0,Math.round((Number(i.valuation.benchmark||0)-deduction)*100)/100);i.valuation.acquisitionValue=i.valuation.acquisitionValue??i.valuation.finalValue;i.valuation.recommendedMax=Math.round(i.valuation.finalValue*(state.settings.offerPct/100)*100)/100;i.valuation.stale=false;i.valuation.confidence=i.valuation.unresolved.length?'partial':i.valuation.adjustments.length?'adjusted':'benchmark';i.needsValuation=i.valuation.unresolved.length>0;}else if(!i.accessories[key]&&['controller','cables'].includes(key)){markValuationStale(i,`${label} removed; replacement adjustment must be refreshed.`);}i.timeline.push(['Completeness',`${label} ${i.accessories[key]?'added':'removed'}.`]);render();};
window.addProcessingCost=id=>{const i=state.items.find(x=>x.id===id),amount=Number(prompt('Processing cost to add (£)','0'));if(!Number.isFinite(amount)||amount<=0)return;const reason=prompt('What was the cost for?','Replacement / repair / cleaning')||'Processing cost';i.processingCosts=Number(i.processingCosts||0)+amount;i.timeline.push(['Processing cost',`${reason}: ${money(amount)}`]);render();};
window.addPhoto=id=>{const i=state.items.find(x=>x.id===id);i.photos++;i.timeline.push(['Photo added','Photo record added.']);render();};window.createListing=id=>{const i=state.items.find(x=>x.id===id),price=Number(prompt('Listing price',marketValue(i)))||marketValue(i);i.listing={channel:'eBay',price,date:today()};i.status='Listed';i.timeline.push(['Listed',`eBay ${money(price)}`]);render();};
window.manualSale=id=>{const items=id?[state.items.find(x=>x.id===id)]:state.items.filter(i=>!i.sale);if(!items.length)return alert('No items available.');open(`<h2>Record sale</h2><div class="formgrid"><div class="field full"><label>Item</label><select id="saleItem" class="select">${items.map(i=>`<option value="${i.id}">${i.title}</option>`).join('')}</select></div><div class="field"><label>Channel</label><select id="saleChannel" class="select">${Object.keys(state.settings.fees).map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Sale price</label><input id="salePrice" class="input" type="number"></div><div class="field"><label>Fee type</label><select id="feeType" class="select"><option value="percent">Percentage</option><option value="fixed">Fixed</option></select></div><div class="field"><label>Fee value</label><input id="feeValue" class="input" type="number" value="12.8"></div>
<div class="field"><label>Trade account</label><select id="saleCustomer" class="select"><option value="">No trade account</option>${state.customers.map(c=>`<option value="${c.id}">${c.name} · ${money(c.credit)} available</option>`).join('')}</select></div>
<div class="field"><label>Use trade credit</label><input id="saleCredit" class="input" type="number" value="0"></div>
</div><div class="modal-actions"><button class="btn primary" onclick="saveSale()">Save sale</button></div>`);};window.saveSale=()=>{
 const i=state.items.find(x=>x.id===Number($('#saleItem').value));
 const channel=$('#saleChannel').value, price=Number($('#salePrice').value);
 const cid=Number($('#saleCustomer')?.value)||null;
 let creditUse=Number($('#saleCredit')?.value)||0;
 if(cid){
   const c=state.customers.find(x=>x.id===cid);
   creditUse=Math.min(creditUse,c.credit,price);
   c.credit-=creditUse;
   c.ledger.push([today(),`Trade credit redeemed · ${i.title}`,-creditUse]);
 }
 const inStore=channel==='In Store EPOS'||channel==='Manual / Cash';
 i.sale={channel,price,feeType:$('#feeType').value,feeValue:Number($('#feeValue').value),shipping:0,packaging:0,date:today(),status:inStore?'Collected in store':'Ready to dispatch',customerId:cid,creditUsed:creditUse};
 i.status=inStore?'Completed':'Sold';
 i.timeline.push(['Sold',`${channel} ${money(price)}${creditUse?` · ${money(creditUse)} trade credit`:''}`]);
 if(inStore)i.timeline.push(['Completed','Collected in store / sale completed.']);
 closeModal();go('sales');
};
window.setReportPeriod=p=>{state.reportPeriod=p;render();};
window.saveNotes=id=>{const i=state.items.find(x=>x.id===id);i.notes=$('#notes').value;i.timeline.push(['Notes','Notes updated.']);render();};window.saveSettings=()=>{state.settings.offerPct=Number($('#offerPct').value);state.settings.storeCreditBonus=Number($('#creditBonus').value);state.settings.greenMargin=Number($('#green').value);state.settings.yellowMargin=Number($('#yellow').value);state.settings.accessoryAllowances=state.settings.accessoryAllowances||{};state.settings.accessoryAllowances.cables=Math.max(0,Number($('#cableAllowance')?.value)||0);render();};window.editFeePreset=()=>{const channel=prompt('Channel: eBay, Vinted, In Store EPOS, Manual / Cash, Website');if(!state.settings.fees[channel])return;const type=prompt('Type: percent or fixed',state.settings.fees[channel].type),value=Number(prompt('Value',state.settings.fees[channel].value));state.settings.fees[channel]={type,value};render();};
$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view);});$('#menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));backdrop.addEventListener('click',e=>{if(e.target===backdrop)closeModal();});
render();
})();
